#!/usr/bin/env bash
# Final stage of the Phase-1 coverage ablation. Waits until BOTH prerequisites
# are ready, then measures how much of GCC 14's own code each corpus exercises:
#
#   - run2   (Phase 1 ON ) : outputs/huf_saem_1phase_10k_run2  (10k programs, already on disk)
#   - baseline (Phase 1 OFF): outputs/huf_saem_baseline_10k     (generated by the queued run)
#
# METHOD: recompile every .fuzz in a corpus with the instrumented gcc at
# `-O2 -std=c++23 -c` (so the optimization passes Phase 1 targets actually run),
# resetting gcov counters between corpora, then capture line/function coverage.
# Programs that fail to compile still contribute the front-end coverage they
# reached -- this reflects the real fuzzing output of each arm.
set -uo pipefail

REPO=/home/ec2-user/HUF-SAEM
PREFIX=/home/ec2-user/gcc-cov
BUILD=/home/ec2-user/gcc-cov-build
SRC=/home/ec2-user/gcc-cov-src
GXX="$PREFIX/bin/g++"
# IMPORTANT: read coverage with the SYSTEM gcov, NOT $PREFIX/bin/gcov.
# gcc-cov was configured with --disable-bootstrap, so the host system gcc
# (11.5) compiled it and stamped every .gcno/.gcda in GCC-11 format. The
# freshly-built $PREFIX/bin/gcov (14.x) core-dumps on that data
# ("version 'B15R', prefer 'B43*'"), yielding 0% coverage. The matching
# reader is the host gcov that produced the instrumentation.
GCOV=/usr/bin/gcov
# run2 generated 10000 programs but the baseline capped at 5856 in 24h (Phase 1
# OFF generates ~3.5x larger programs, so it is ~2.7x slower per program). To
# equalize program COUNT, point at a symlink dir holding run2's first 5856
# programs (indices 0..5855, matching the baseline's set). NOTE: this equalizes
# count but not total code volume -- baseline still has ~3.5x more source.
RUN2="$REPO/outputs/huf_saem_1phase_10k_run2_trunc5856"
BASE="$REPO/outputs/huf_saem_baseline_10k"
OUT="$REPO/coverage_comparison.txt"
CFLAGS="-std=c++23 -O2 -c"
# lcov 2.0 promotes benign gcov warnings ("unexecuted block on non-branch line",
# source/mismatch notes) to FATAL errors by default, which made the probe below
# wrongly "fail" and fall back to gcovr even though lcov read all 616 data files
# correctly. Demote those to warnings and zero out unexecuted blocks.
LCOV_OPTS="--ignore-errors gcov,source,mismatch,unused,empty,negative --rc geninfo_unexecuted_blocks=1"

ts() { date -u '+%Y-%m-%d %H:%M:%S'; }
cd "$REPO"

# 1. Wait for the instrumented gcc build to finish.
echo "[coverage $(ts)] waiting for instrumented gcc build ..."
while ! { [ -x "$GXX" ] && grep -q "^\[gccbuild.*DONE" gcc_build.log 2>/dev/null; }; do
    if grep -qE "FAILED" gcc_build.log 2>/dev/null; then
        echo "[coverage $(ts)] ABORT: gcc build reported failure. See gcc_build.log"; exit 1
    fi
    sleep 120
done
echo "[coverage $(ts)] instrumented gcc ready: $($GXX --version | head -1)"

# 2. Wait for the baseline run to finish (its revalidation file is the last thing written).
echo "[coverage $(ts)] waiting for baseline_10k to finish ..."
while [ ! -f "$REPO/baseline_gcc14_revalidation.txt" ]; do sleep 120; done
echo "[coverage $(ts)] baseline ready ($(ls -1 $BASE/*.fuzz 2>/dev/null | wc -l) programs)"

# 3. Decide coverage tool: prefer lcov, fall back to gcovr if lcov/gcov disagree.
COV_TOOL=lcov
echo 'int main(){return 0;}' > /tmp/cov_probe.cpp
( cd "$BUILD" && find . -name '*.gcda' -delete )
"$GXX" $CFLAGS /tmp/cov_probe.cpp -o /tmp/cov_probe.o 2>/dev/null
if ! lcov --gcov-tool "$GCOV" --capture --directory "$BUILD" $LCOV_OPTS \
        --output-file /tmp/cov_probe.info >/tmp/lcov_probe.log 2>&1; then
    echo "[coverage $(ts)] lcov probe failed; falling back to gcovr"
    pip install -q gcovr >/dev/null 2>&1
    COV_TOOL=gcovr
fi
echo "[coverage $(ts)] coverage tool: $COV_TOOL"

collect() {  # $1=corpus dir  $2=label
    local dir="$1" label="$2" n=0
    echo "[coverage $(ts)] [$label] resetting counters ..."
    ( cd "$BUILD" && find . -name '*.gcda' -delete )
    echo "[coverage $(ts)] [$label] compiling $(ls -1 $dir/*.fuzz 2>/dev/null | wc -l) programs (serial, $CFLAGS) ..."
    for f in "$dir"/*.fuzz; do
        timeout 30 "$GXX" $CFLAGS "$f" -o /tmp/cov_obj.o >/dev/null 2>&1
        n=$((n+1)); [ $((n % 1000)) -eq 0 ] && echo "[coverage $(ts)] [$label]   $n compiled"
    done
    echo "[coverage $(ts)] [$label] capturing coverage ..."
    if [ "$COV_TOOL" = lcov ]; then
        lcov --gcov-tool "$GCOV" --capture --directory "$BUILD" $LCOV_OPTS \
             --output-file "$REPO/cov_$label.info" >/dev/null 2>&1
        { echo "===== $label (Phase 1 = $3) ====="; lcov --summary "$REPO/cov_$label.info" 2>&1; echo; } >> "$OUT"
    else
        # Filter to GCC's own source (-r $SRC), but the .gcda/.gcno live in the
        # BUILD tree -- pass $BUILD as the explicit search path so gcovr finds
        # them (the old `-r gcc-cov-src` searched the source tree, which holds
        # no coverage data). Run from $BUILD so gcov's relative object paths
        # resolve, and tolerate per-file gcov hiccups instead of aborting.
        ( cd "$BUILD" && gcovr --gcov-executable "$GCOV" -r "$SRC" "$BUILD" \
            --gcov-ignore-errors=no_working_dir_found \
            --print-summary -o "$REPO/cov_$label.txt" ) >> "$OUT" 2>&1
    fi
}

: > "$OUT"
{ echo "PHASE-1 COVERAGE ABLATION — GCC 14.2 (instrumented), recompiled at $CFLAGS"; echo "generated $(ts)"; echo; } >> "$OUT"
collect "$RUN2" "run2_phase1"   "ON"
collect "$BASE" "baseline"      "OFF"

echo "[coverage $(ts)] DONE. Comparison -> $OUT"
cat "$OUT"
